```
[Script]
http-response ^https?:\/\/www\.pkulaw\.com\/chl\/.+ requires-body=true, script-path=pkulaw.js
[MITM]
hostname = www.pkulaw.com
```
```pkulaw.js
if ($request.url.includes('keyword=')) {
$done({
status: 307,
headers: {
'Location': $request.url.replace(/\?keyword=.+/, '')
}
})
}
$done({})
```

